import type { InputReader, SellerEntry } from '../domain/contracts.js';

export class JsonInputReader implements InputReader {
  read(bytes: string): readonly SellerEntry[] {
    const parsed: unknown = JSON.parse(bytes);
    if (!Array.isArray(parsed)) {
      throw new Error('Input must contain a JSON array.');
    }

    return parsed.map((row, index) => {
      if (typeof row !== 'object' || row === null) {
        throw new Error(`Input row ${index + 1} must be an object.`);
      }
      const candidate = row as Record<string, unknown>;
      if (typeof candidate.Id !== 'string' || typeof candidate.SellerName !== 'string') {
        throw new Error(`Input row ${index + 1} requires string Id and SellerName fields.`);
      }
      return { id: candidate.Id, sellerName: candidate.SellerName };
    });
  }
}

